import { DEFAULT_AUDIO_FILE_NAME, DEFAULT_AUDIO_MIME } from "./constants.js";
import { int16ToBytes } from "./pcm.js";
export function createDefaultAudioPart(pcm) {
  const bytes = int16ToBytes(pcm);
  if (typeof File === "function") {
    try {
      return new File([bytes], DEFAULT_AUDIO_FILE_NAME, {
        type: DEFAULT_AUDIO_MIME,
      });
    } catch {
      return new Blob([bytes], { type: DEFAULT_AUDIO_MIME });
    }
  }
  return new Blob([bytes], { type: DEFAULT_AUDIO_MIME });
}
export function serializeMultipartBody(body) {
  const data = new FormData();
  if (!body || typeof body !== "object") return data;
  for (const [key, value] of Object.entries(body)) {
    if (value === undefined || value === null) continue;
    if (Array.isArray(value)) {
      for (const item of value) appendFormValue(data, key, item);
      continue;
    }
    appendFormValue(data, key, value);
  }
  return data;
}
export function createRestClientTransport(api, options = {}) {
  const serviceName = options.serviceName ?? "";
  const createAudioPart = options.createAudioPart ?? createDefaultAudioPart;
  const resolveApi = () => {
    if (typeof api === "function") return Promise.resolve(api());
    return Promise.resolve(api);
  };
  const callOptions = (signal) => ({
    throwOnError: true,
    signal,
    bodySerializer: serializeMultipartBody,
  });
  return {
    async start(input) {
      const client = await resolveApi();
      const data = await client.startDictation(
        { "x-service": serviceName },
        { throwOnError: true, signal: input.signal }
      );
      if (!data?.dictationId)
        throw new Error("Dictation start response missing dictationId");
      return { dictationId: data.dictationId };
    },
    async transcribeChunk(input) {
      const client = await resolveApi();
      const data = await client.transcribeDictationChunk(
        {
          "x-service": serviceName,
          transcribeDictationChunkDto: {
            audio: createAudioPart(input.audio),
            dictationId: input.dictationId,
            chunkIndex: input.chunkIndex,
            ...(input.previousText ? { previousText: input.previousText } : {}),
            ...(input.languages?.length ? { languages: input.languages } : {}),
          },
        },
        callOptions(input.signal)
      );
      if (!data) throw new Error("Dictation chunk response missing body");
      return { rawText: data.rawText };
    },
    async finish(input) {
      const client = await resolveApi();
      const data = await client.finishDictation(
        {
          "x-service": serviceName,
          finishDictationDto: {
            ...(input.audio ? { audio: createAudioPart(input.audio) } : {}),
            previousText: input.previousText,
            dictationId: input.dictationId,
            ...(input.chunkIndex === undefined
              ? {}
              : { chunkIndex: input.chunkIndex }),
            chunkCount: input.chunkCount,
            recordingDurationMs: input.recordingDurationMs,
            ...(input.releasedKeyAt === undefined
              ? {}
              : { releasedKeyAt: toIsoString(input.releasedKeyAt) }),
            ...(input.screenContext
              ? { screenContext: input.screenContext }
              : {}),
            ...(input.disableFormatting ? { disableFormatting: true } : {}),
            ...(input.languages?.length ? { languages: input.languages } : {}),
            ...(input.provider ? { provider: input.provider } : {}),
          },
        },
        callOptions(input.signal)
      );
      if (!data) throw new Error("Dictation finish response missing body");
      return {
        cleanedText: data.cleanedText,
        rawText: data.rawText,
        dictationId: data.dictationId,
      };
    },
    async process(input) {
      const client = await resolveApi();
      const data = await client.processDictation(
        {
          "x-service": serviceName,
          processDictationDto: {
            audio: createAudioPart(input.audio),
            ...(input.dictationId ? { dictationId: input.dictationId } : {}),
            ...(input.releasedKeyAt === undefined
              ? {}
              : { releasedKeyAt: toIsoString(input.releasedKeyAt) }),
            ...(input.screenContext
              ? { screenContext: input.screenContext }
              : {}),
            ...(input.disableFormatting ? { disableFormatting: true } : {}),
            ...(input.languages?.length ? { languages: input.languages } : {}),
          },
        },
        callOptions(input.signal)
      );
      if (!data) throw new Error("Dictation process response missing body");
      return {
        cleanedText: data.cleanedText,
        rawText: data.rawText,
        dictationId: data.dictationId,
      };
    },
    async format(input) {
      const client = await resolveApi();
      const data = await client.formatDictation(
        {
          "x-service": serviceName,
          formatDictationDto: {
            rawText: input.rawText,
            ...(input.dictationId ? { dictationId: input.dictationId } : {}),
            ...(input.releasedKeyAt === undefined
              ? {}
              : { releasedKeyAt: toIsoString(input.releasedKeyAt) }),
            ...(input.screenContext
              ? { screenContext: input.screenContext }
              : {}),
            ...(input.languages?.length ? { languages: input.languages } : {}),
            ...(input.recordingDurationMs === undefined
              ? {}
              : { recordingDurationMs: input.recordingDurationMs }),
            ...(input.provider ? { provider: input.provider } : {}),
          },
        },
        { throwOnError: true, signal: input.signal }
      );
      if (!data) throw new Error("Dictation format response missing body");
      return { cleanedText: data.cleanedText };
    },
  };
}
export function toIsoString(value) {
  if (value instanceof Date) return value.toISOString();
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return value;
  return parsed.toISOString();
}
function appendFormValue(data, key, value) {
  if (typeof value === "string") {
    data.append(key, value);
    return;
  }
  if (typeof Blob === "function" && value instanceof Blob) {
    data.append(key, value);
    return;
  }
  if (isUriPart(value)) {
    data.append(key, value);
    return;
  }
  if (value instanceof Date) {
    data.append(key, value.toISOString());
    return;
  }
  data.append(key, JSON.stringify(value));
}
function isUriPart(value) {
  if (!value || typeof value !== "object") return false;
  return "uri" in value && typeof value.uri === "string";
}
